import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    results = []

    idx = 1
    for _ in range(t):
        s = input_data[idx]
        idx += 1

        has_e = False
        has_n = False

        for char in s:
            if char == 'E':
                has_e = True
            elif char == 'N':
                has_n = True

        if has_e and has_n:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
